Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -40,4 +40,38 @@
 <div class="pause-cover" id="pause">PAUSED</div>
 <div class="controls" id="controls"><div class="cluster"><div class="dpad"><button class="ctrl up" data-key="w">▲</button><button class="ctrl left" data-key="a">◀</button><button class="ctrl down" data-key="s">▼</button><button class="ctrl right" data-key="d">▶</button></div></div><div class="cluster actions"><button class="ctrl punch" data-key="j">PUNCH</button><button class="ctrl kick" data-key="k">KICK</button><button class="ctrl special" data-key="q">PHOENIX</button><button class="ctrl special" data-key="e">RUSH</button><button class="ctrl guard" data-key=" ">GUARD</button></div></div>
 </main>
 <script>
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
+const gameEl=document.getElementById('game');
+const ui={pHealth:document.getElementById('p-health'),eHealth:document.getElementById('e-health'),pMeter:document.getElementById('p-meter'),eMeter:document.getElementById('e-meter'),timer:document.getElementById('timer'),announce:document.getElementById('announce'),intro:document.getElementById('intro'),result:document.getElementById('result'),pause:document.getElementById('pause')};
+let W=1000,H=625,dpr=1,last=0,elapsed=0,playing=false,paused=false,roundOver=false,screenShake=0,announceTimeout=0,soundOn=true,audio;
+const keys=new Set(),particles=[],projectiles=[],sparks=[];
+const floorY=500;
+const p={x:330,y:0,vx:0,vy:0,health:100,meter:0,facing:1,face:1,action:'idle',actionT:0,stun:0,attackCd:0,combo:0,comboT:0,guard:false,air:0,color:'#f25069',skin:'#e9ae88',name:'KAI',cpu:false};
+const e={x:670,y:0,vx:0,vy:0,health:100,meter:0,facing:-1,face:-1,action:'idle',actionT:0,stun:0,attackCd:0,combo:0,comboT:0,guard:false,air:0,color:'#35c8d1',skin:'#b87c66',name:'VEX',cpu:true};
+function resize(){const r=gameEl.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);W=1000;H=625;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}window.addEventListener('resize',resize);resize();
+function sound(freq=220,dur=.07,type='square',vol=.035){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
+function announce(text,delay=900){ui.announce.textContent=text;ui.announce.classList.add('show');clearTimeout(announceTimeout);announceTimeout=setTimeout(()=>ui.announce.classList.remove('show'),delay)}
+function resetRound(){Object.assign(p,{x:330,y:0,vx:0,vy:0,health:100,meter:0,action:'idle',actionT:0,stun:0,attackCd:0,combo:0,comboT:0});Object.assign(e,{x:670,y:0,vx:0,vy:0,health:100,meter:0,action:'idle',actionT:0,stun:0,attackCd:0,combo:0,comboT:0});projectiles.length=particles.length=0;elapsed=0;roundOver=false;ui.timer.textContent='60';syncHud()}
+function startGame(){resetRound();playing=true;paused=false;ui.pause.classList.remove('show');ui.intro.classList.add('hidden');ui.result.classList.add('hidden');announce('FIGHT!',900);sound(440,.13,'triangle')}
+document.getElementById('start').onclick=startGame;document.getElementById('rematch').onclick=startGame;
+document.getElementById('sound').onclick=()=>{soundOn=!soundOn;document.getElementById('sound').textContent=soundOn?'♫':'♪';if(soundOn)sound(600,.06,'sine')};
+function setKey(k,on){if(on){if(!keys.has(k)){keys.add(k);pressed.add(k)}}else keys.delete(k)}const pressed=new Set();
+window.addEventListener('keydown',ev=>{const k=ev.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))ev.preventDefault();if(k==='escape'||k==='p'){if(playing&&!roundOver){paused=!paused;ui.pause.classList.toggle('show',paused)}return}setKey(k,true)});window.addEventListener('keyup',ev=>setKey(ev.key.toLowerCase(),false));
+document.querySelectorAll('.ctrl').forEach(btn=>{const k=btn.dataset.key;btn.addEventListener('pointerdown',ev=>{ev.preventDefault();btn.setPointerCapture(ev.pointerId);btn.classList.add('pressed');setKey(k,true)});for(const n of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(n,()=>{btn.classList.remove('pressed');setKey(k,false)})});
+function syncHud(){ui.pHealth.style.width=Math.max(0,p.health)+'%';ui.eHealth.style.width=Math.max(0,e.health)+'%';ui.pMeter.style.width=p.meter+'%';ui.eMeter.style.width=e.meter+'%';ui.timer.textContent=Math.max(0,60-Math.floor(elapsed)).toString().padStart(2,'0')}
+function puff(x,y,color,n=8,power=3){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*power*2,vy:(Math.random()-.7)*power*2,life:.25+Math.random()*.4,size:2+Math.random()*5,color})}
+function attack(f,type){if(f.stun>0||f.attackCd>0||f.action==='ko'||f.health<=0)return;if(type==='special'&&f.meter<25){announce('NEED 25% ENERGY',650);sound(120,.06,'sine');return}
+if(type==='special'){f.meter-=25;const choice=f.cpu?Math.floor(Math.random()*3):((keys.has('q')?0:keys.has('e')?1:2));if(choice===0){f.action='phoenix';f.actionT=.8;f.vy=-550;f.vx=f.facing*190;f.attackCd=1.2;f.air=1;puff(f.x,floorY-f.y,'#ffb35a',15,5);announce('RISING PHOENIX!',700);sound(520,.18,'sawtooth')}else if(choice===1){f.action='rush';f.actionT=.55;f.vx=f.facing*690;f.attackCd=1;projectiles.push({x:f.x+f.facing*35,y:floorY-f.y-62,vx:f.facing*390,life:1.2,owner:f,kind:'rush',color:f.color});announce('COMET RUSH!',650);sound(260,.16,'sawtooth')}else{f.action='starfall';f.actionT=.65;f.attackCd=1.15;projectiles.push({x:f.x+f.facing*45,y:floorY-f.y-75,vx:f.facing*300,life:1.3,owner:f,kind:'star',color:'#ffca70'});announce('STARFALL!',650);sound(740,.2,'triangle')}return}
+f.action=type;f.actionT=type==='kick'?.42:.31;f.attackCd=type==='kick'?.52:.34;sound(type==='kick'?170:260,.065,type==='kick'?'triangle':'square',.025)}
+function strike(f,target,kind){const reach=kind==='kick'?96:kind==='phoenix'?80:kind==='rush'?78:kind==='star'?75:66;const height=kind==='kick'?floorY-f.y-35:floorY-f.y-75;const dx=target.x-f.x;const inRange=Math.abs(dx)<reach&&Math.abs((target.y||0)-f.y)<100; if(!inRange||dx*f.facing<0)return false;
+const blocking=target.guard&&target.stun<=0&&target.facing===-f.facing;let dmg=kind==='kick'?10:kind==='punch'?7:kind==='phoenix'?17:kind==='rush'?14:kind==='star'?15:12; if(blocking){dmg*=.18;target.stun=.16;puff(target.x+target.facing*18,floorY-target.y-55,'#8deaff',5,2);sound(90,.08,'sine')}else{target.stun=kind==='star'||kind==='phoenix'?.6:.34;target.vx=f.facing*(kind==='rush'?310:kind==='phoenix'?250:180);if(kind==='phoenix')target.vy=-150;target.action='hit';target.actionT=.32;target.health=Math.max(0,target.health-dmg);f.meter=Math.min(100,f.meter+(kind==='punch'?8:kind==='kick'?10:4));target.combo++;target.comboT=1.25;puff(target.x-f.facing*16,floorY-target.y-62,kind==='star'?'#ffdc83':f.color,12,4);sparks.push({x:target.x,y:floorY-target.y-65,life:.2});screenShake=7;sound(kind==='kick'?110:kind==='star'?500:145,.1,'sawtooth',.045);if(f===p&&target.combo>1)announce(target.combo+' HIT!',450)}return true}
+function updateFighter(f,dt){if(f.health<=0){f.action='ko';return}f.attackCd=Math.max(0,f.attackCd-dt);f.stun=Math.max(0,f.stun-dt);f.comboT=Math.max(0,f.comboT-dt);if(f.comboT===0)f.combo=0;f.actionT=Math.max(0,f.actionT-dt);if(f.actionT===0&&['punch','kick','phoenix','rush','starfall','hit'].includes(f.action))f.action='idle';f.guard=false;
+if(f.stun<=0){if(f===p){let move=(keys.has('a')?-1:0)+(keys.has('d')?1:0);f.guard=keys.has(' ');if(move){f.vx+=move*1600*dt;f.vx=Math.max(-260,Math.min(260,f.vx))}else f.vx*=Math.pow(.001,dt);if(keys.has('w')&&f.y===0&&!keys.has('wWas')){f.vy=-510;f.air=0;sound(300,.06,'triangle')}if(keys.has('j'))attack(f,'punch');if(keys.has('k'))attack(f,'kick');if(keys.has('q')||keys.has('e')||keys.has('r'))attack(f,'special')}
+else{const dx=p.x-f.x,dist=Math.abs(dx),dir=Math.sign(dx);if(dist>112){f.vx+=dir*560*dt;f.vx=Math.max(-190,Math.min(190,f.vx))}else f.vx*=Math.pow(.001,dt);f.guard=dist<135&&Math.random()<.025;if(f.attackCd<=0){if(dist<105&&Math.random()<dt*1.6)attack(f,Math.random()<.52?'punch':'kick');else if(dist>160&&dist<370&&f.meter>=25&&Math.random()<dt*.55){const before=f.meter;f.meter=100;attack(f,'special');f.meter=Math.min(before,f.meter+25)}}}}
+f.vy+=1450*dt;f.y+=f.vy*dt;if(f.y<0){f.y=0;f.vy=0;f.air=0}f.x+=f.vx*dt;f.x=Math.max(95,Math.min(905,f.x));if(f.action!=='rush')f.vx*=Math.pow(.07,dt);f.facing=f===p?(p.x<e.x?1:-1):(e.x<p.x?1:-1);f.face=f.facing;
+}
+function update(dt){if(!playing||paused||roundOver)return;elapsed+=dt;for(const f of [p,e])updateFighter(f,dt);if(keys.has('j')&&p.action==='punch'&&p.actionT>.12)strike(p,e,'punch');if(keys.has('k')&&p.action==='kick'&&p.actionT>.18)strike(p,e,'kick');if(e.action==='punch'&&e.actionT>.13)strike(e,p,'punch');if(e.action==='kick'&&e.actionT>.18)strike(e,p,'kick');if(p.action==='phoenix'&&p.actionT>.42)strike(p,e,'phoenix');if(e.action==='phoenix'&&e.actionT>.42)strike(e,p,'phoenix');if(p.action==='rush'&&p.actionT>.25)strike(p,e,'rush');if(e.action==='rush'&&e.actionT>.25)strike(e,p,'rush');
+for(let i=projectiles.length-1;i>=0;i--){const a=projectiles[i];a.x+=a.vx*dt;a.life-=dt;if(a.life<=0||a.x<30||a.x>970){projectiles.splice(i,1);continue}const target=a.owner===p?e:p;if(Math.abs(a.x-target.x)<36&&Math.abs((floorY-target.y-60)-a.y)<66){strike(a.owner,target,a.kind);puff(a.x,a.y,a.color,10,4);projectiles.splice(i,1)}}
+for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.x+=a.vx;a.y+=a.vy;a.vy+=130*dt;a.life-=dt;if(a.life<=0)particles.splice(i,1)}sparks.forEach(a=>a.life-=dt);while(sparks.length&&sparks[0].life<=0)sparks.shift();screenShake=Math.max(0,screenShake-dt*28);syncHud();if(p.health<=0||e.health<=0||elapsed>=60)finishRound()}
+function finishRound(){if(roundOver)return;roundOver=true;playing=false;const win=p.health>e.health;ui['result-title'].innerHTML=win?'K.O.<span>VICTORY</span>':'K.O.<span>DEFEAT</span>';document.getElementById('result-sub').textContent=win?'The rooftop belongs to you.':'Vex owns the skyline tonight.';document.getElementById('result-kicker').textContent=win?'THE CROWD GOES WILD':'BACK TO THE DOJO';ui.result.classList.remove('hidden');sound(win?660:100,.5,win?'triangle':'sawtooth')}

