function finishRound(){if(roundOver)return;roundOver=true;playing=false;const win=p.health>e.health;document.getElementById('result-title').innerHTML=win?'K.O.<span>VICTORY</span>':'K.O.<span>DEFEAT</span>';document.getElementById('result-sub').textContent=win?'The rooftop belongs to you.':'Vex owns the skyline tonight.';document.getElementById('result-kicker').textContent=win?'THE CROWD GOES WILD':'BACK TO THE DOJO';ui.result.classList.remove('hidden');sound(win?660:100,.5,win?'triangle':'sawtooth')}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#11172d');g.addColorStop(.52,'#28304b');g.addColorStop(1,'#e56a78');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// Moon and halo
const halo=ctx.createRadialGradient(744,145,5,744,145,155);halo.addColorStop(0,'#ffe9c2aa');halo.addColorStop(.22,'#ffb77a38');halo.addColorStop(1,'#ffac7020');ctx.fillStyle=halo;ctx.fillRect(560,0,360,330);ctx.fillStyle='#ffe5bc';ctx.beginPath();ctx.arc(744,145,35,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e99c94';ctx.beginPath();ctx.arc(757,136,35,0,Math.PI*2);ctx.fill();
// stars
for(let i=0;i<60;i++){let x=(i*173+59)%W,y=(i*89+17)%270;ctx.globalAlpha=.23+(i%4)*.12;ctx.fillStyle='#fff4d8';ctx.fillRect(x,y,i%7===0?2:1,1)}ctx.globalAlpha=1;
// distant city
for(let layer=0;layer<3;layer++){const base=345+layer*45;for(let i=0;i<16;i++){const x=i*76-22+layer*13,bw=42+(i*17%35),bh=75+((i*73+layer*31)%120);ctx.fillStyle=['#202941','#1b233b','#151c31'][layer];ctx.fillRect(x,base-bh,bw,bh+90);ctx.fillStyle=layer===0?'#ffc981':'#fa738b';for(let r=0;r<7;r++)for(let c=0;c<3;c++){if((r*3+c+i)%4===0)continue;ctx.globalAlpha=.17+((r+c+i)%3)*.07;ctx.fillRect(x+7+c*10,base-bh+12+r*14,4,7)}ctx.globalAlpha=1}}
// distant neon signage
ctx.save();ctx.translate(124,234);ctx.rotate(-.05);ctx.fillStyle='#18243a';ctx.fillRect(-3,-3,159,55);ctx.strokeStyle='#ff5d83';ctx.lineWidth=2;ctx.strokeRect(0,0,153,49);ctx.shadowColor='#ff527e';ctx.shadowBlur=15;ctx.fillStyle='#ff8da2';ctx.font='900 21px Arial';ctx.fillText('MIDTOWN',10,22);ctx.font='700 11px monospace';ctx.fillText('街 · NIGHT CITY',10,39);ctx.restore();
// clouds / rooftop structures
ctx.fillStyle='#11182c';ctx.beginPath();ctx.moveTo(0,376);ctx.lineTo(112,349);ctx.lineTo(188,374);ctx.lineTo(188,427);ctx.lineTo(0,427);ctx.fill();ctx.fillRect(814,375,186,52);ctx.fillRect(849,338,117,44);ctx.fillStyle='#46516a';ctx.fillRect(827,368,7,60);ctx.fillRect(839,365,4,64);
// far crowd silhouettes
for(let i=0;i<42;i++){let x=i*25,y=447+(i%4)*5;ctx.fillStyle=i%3?'#131a2d':'#29223a';ctx.beginPath();ctx.arc(x,y-13,6,0,Math.PI*2);ctx.fill();ctx.fillRect(x-5,y-9,10,17);if(i%6===0){ctx.strokeStyle='#ff6787aa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y-5);ctx.lineTo(x+(i%2?12:-12),y-21);ctx.stroke()}}
// rooftop floor
const floor=ctx.createLinearGradient(0,438,0,H);floor.addColorStop(0,'#34334b');floor.addColorStop(.18,'#25283e');floor.addColorStop(1,'#101523');ctx.fillStyle=floor;ctx.fillRect(0,438,W,H-438);ctx.fillStyle='#f77d8d';ctx.globalAlpha=.45;ctx.fillRect(0,439,W,2);ctx.globalAlpha=1;
// perspective seams
ctx.strokeStyle='#8c718966';ctx.lineWidth=1;for(let i=-5;i<14;i++){ctx.beginPath();ctx.moveTo(500,440);ctx.lineTo(i*120,625);ctx.stroke()}for(let y of [462,491,530,584]){ctx.globalAlpha=.2+(y-462)/500;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;
// roof vents and painted ring
ctx.fillStyle='#141b2d';ctx.fillRect(20,461,100,16);ctx.fillStyle='#44435a';ctx.fillRect(28,455,83,7);ctx.fillStyle='#141b2d';ctx.fillRect(872,469,95,13);ctx.fillStyle='#565068';ctx.fillRect(882,461,77,8);ctx.strokeStyle='#ffc777';ctx.globalAlpha=.55;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(500,510,285,32,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;
}
function drawFighter(f){const ground=floorY-f.y;const walk=Math.abs(f.vx)>35?Math.sin(performance.now()*.018+(f===p?0:2)):0;const face=f.facing;ctx.save();ctx.translate(f.x,ground);ctx.scale(face,1);const c=f.color;const attacking=['punch','kick','phoenix','rush','starfall'].includes(f.action);const hit=f.action==='hit'||f.stun>0;const guard=f.guard;const crouch=keys.has('s')&&f===p;const bob=Math.sin(performance.now()*.004+(f===p?0:2))*2;
// shadow
ctx.save();ctx.scale(1,.27);ctx.fillStyle='#06091488';ctx.beginPath();ctx.ellipse(0,6,43+f.y*.04,16,0,0,Math.PI*2);ctx.fill();ctx.restore();
if(f.action==='phoenix'||f.action==='rush'){ctx.globalAlpha=.28;for(let i=3;i>0;i--){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(-face*i*16,-64,21,54,.4,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
ctx.translate(0,bob);if(f.action==='phoenix')ctx.rotate(-.24);if(hit)ctx.rotate(-.17);
// rear leg, animated stepping
const step=walk*10;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#171c2d';ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(-5,-36);ctx.lineTo(-14-step,-16);ctx.lineTo(-20-step,-4);ctx.stroke();ctx.strokeStyle=c;ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-8,-34);ctx.lineTo(-14-step,-17);ctx.stroke();ctx.fillStyle='#151a28';rr(-31-step,-8,24,9,4);
// lead leg or kick
ctx.strokeStyle='#1a2030';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(7,-37);if(f.action==='kick'){ctx.lineTo(32,-46);ctx.lineTo(63,-55)}else{ctx.lineTo(15+step,-17);ctx.lineTo(20+step,-4)}ctx.stroke();ctx.strokeStyle=c;ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(8,-38);if(f.action==='kick'){ctx.lineTo(32,-46);ctx.lineTo(57,-54)}else{ctx.lineTo(15+step,-18)}ctx.stroke();ctx.fillStyle='#171c2d';if(f.action==='kick')rr(48,-59,24,11,5);else rr(10+step,-8,24,9,4);
// torso silhouette
ctx.fillStyle='#141a2b';ctx.beginPath();ctx.moveTo(-17,-86);ctx.quadraticCurveTo(-24,-67,-17,-39);ctx.lineTo(17,-39);ctx.quadraticCurveTo(23,-69,15,-86);ctx.closePath();ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-14,-83);ctx.lineTo(13,-83);ctx.lineTo(16,-47);ctx.lineTo(-16,-47);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.globalAlpha=.25;ctx.fillRect(-3,-81,4,31);ctx.globalAlpha=1;
// belt and sash
ctx.fillStyle='#101525';ctx.fillRect(-17,-52,34,7);ctx.fillStyle=f===p?'#ffe08c':'#d7f6f1';ctx.fillRect(-4,-53,8,7);if(f===p){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(10,-53);ctx.lineTo(24,-48);ctx.lineTo(31,-22);ctx.lineTo(20,-32);ctx.lineTo(12,-44);ctx.fill()}
// arms
const punchOut=f.action==='punch'||f.action==='rush'||f.action==='starfall';ctx.lineCap='round';ctx.strokeStyle='#151a2a';ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(-13,-78);ctx.lineTo(-25,-65);ctx.lineTo(-20,-55);ctx.stroke();ctx.strokeStyle=f.skin;ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-13,-78);ctx.lineTo(-25,-65);ctx.lineTo(-20,-55);ctx.stroke();
ctx.strokeStyle='#151a2a';ctx.lineWidth=16;ctx.beginPath();ctx.moveTo(12,-78);if(guard){ctx.lineTo(27,-91);ctx.lineTo(11,-105)}else if(punchOut){ctx.lineTo(27,-74);ctx.lineTo(48,-74)}else{ctx.lineTo(27,-66);ctx.lineTo(20,-56)}ctx.stroke();ctx.strokeStyle=f.skin;ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(12,-78);if(guard){ctx.lineTo(27,-91);ctx.lineTo(11,-105)}else if(punchOut){ctx.lineTo(27,-74);ctx.lineTo(43,-74)}else{ctx.lineTo(27,-66);ctx.lineTo(20,-56)}ctx.stroke();
// hand wraps
ctx.fillStyle='#f4e4cc';if(punchOut)rr(39,-81,16,15,5);else rr(14,-60,13,9,4);if(guard)rr(4,-110,16,14,5);
// neck/head
ctx.fillStyle=f.skin;rr(-7,-94,14,15,5);ctx.fillStyle=f.skin;ctx.beginPath();ctx.ellipse(0,-105,16,19,0,0,Math.PI*2);ctx.fill();
// hair silhouette
ctx.fillStyle=f===p?'#201a26':'#121b2c';ctx.beginPath();if(f===p){ctx.moveTo(-15,-106);ctx.lineTo(-18,-124);ctx.lineTo(-8,-117);ctx.lineTo(-5,-133);ctx.lineTo(4,-119);ctx.lineTo(13,-126);ctx.lineTo(15,-108);ctx.closePath()}else{ctx.moveTo(-16,-105);ctx.lineTo(-13,-122);ctx.quadraticCurveTo(1,-133,16,-119);ctx.lineTo(15,-106);ctx.lineTo(6,-111);ctx.lineTo(-6,-108);ctx.closePath()}ctx.fill();
// face details, eye faces forward (right in local coords)
ctx.fillStyle='#201e2b';ctx.beginPath();ctx.ellipse(7,-105,2.4,1.8,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#7e4f4e';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(6,-97);ctx.lineTo(12,-98);ctx.stroke();
if(f===p){ctx.fillStyle='#f6d79e';ctx.fillRect(-15,-113,30,4);ctx.fillStyle='#ff566e';ctx.fillRect(-15,-112,30,3)}else{ctx.fillStyle='#68f3ed';ctx.fillRect(-15,-115,29,4);ctx.globalAlpha=.7;ctx.fillStyle='#71faff';ctx.fillRect(-14,-114,27,2);ctx.globalAlpha=1}
if(f.action==='starfall'){ctx.shadowColor='#ffca70';ctx.shadowBlur=18;ctx.fillStyle='#ffdf86';ctx.beginPath();ctx.arc(46,-74,9,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}
