 *{box-sizing:border-box}html,body{height:100%;margin:0;background:#080a13;color:var(--white);font-family:'Barlow Condensed',Impact,sans-serif;overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none}
 body{display:grid;place-items:center;background:radial-gradient(ellipse at 50% 40%,#202441 0,#0a0c17 58%,#070810 100%)}
-#game{position:relative;width:min(100vw,1280px);height:min(100dvh,800px);aspect-ratio:16/10;overflow:hidden;background:#11152b;box-shadow:0 30px 100px #000b;border:1px solid #ffffff20;isolation:isolate}
+#game{position:relative;width:min(100vw,1280px,160dvh);height:min(100dvh,800px,62.5vw);aspect-ratio:16/10;overflow:hidden;background:#11152b;box-shadow:0 30px 100px #000b;border:1px solid #ffffff20;isolation:isolate}
 canvas{position:absolute;inset:0;width:100%;height:100%;display:block;background:radial-gradient(ellipse at 50% 45%,#202441,#090b16 68%)}
 .hud{position:absolute;inset:0;pointer-events:none;z-index:2;padding:clamp(12px,2.4vw,28px);display:flex;flex-direction:column;justify-content:space-between}
 .topline{display:grid;grid-template-columns:1fr auto 1fr;align-items:start;gap:14px}.fighter-hud{min-width:0}.fighter-hud.right{text-align:right}.name-row{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:7px}.right .name-row{flex-direction:row-reverse}.name{font-size:clamp(17px,2.3vw,27px);font-weight:900;letter-spacing:.1em;line-height:1;text-shadow:0 2px 12px #000}.tag{font:10px 'DM Mono',monospace;letter-spacing:.12em;color:#ffffff9a}.bar-shell{height:clamp(13px,2vw,20px);background:#090b16cc;border:1px solid #ffffff50;transform:skewX(-10deg);padding:2px;box-shadow:0 4px 14px #0008}.bar{height:100%;width:100%;background:linear-gradient(90deg,#ff4f79,#ff9b72);transition:width .25s ease;box-shadow:0 0 16px #ff5c8380}.right .bar{margin-left:auto;background:linear-gradient(90deg,#59e9e3,#78a6ff)}.meter{height:5px;margin-top:6px;background:#ffffff1a;transform:skewX(-10deg);overflow:hidden}.meter-fill{height:100%;width:0%;background:linear-gradient(90deg,var(--gold),#ffef9d);box-shadow:0 0 10px var(--gold);transition:width .2s}.right .meter-fill{margin-left:auto}.center-hud{text-align:center;min-width:70px}.round-label{font:9px 'DM Mono',monospace;letter-spacing:.2em;color:#ffffff8a}.timer{font-size:clamp(29px,4vw,46px);font-weight:900;line-height:.9;text-shadow:0 2px 15px #000}.round-dots{display:flex;gap:5px;justify-content:center;margin-top:7px}.round-dots i{width:7px;height:7px;border:1px solid #ffffff88;border-radius:50%}.round-dots i.won{background:var(--gold);border-color:var(--gold);box-shadow:0 0 8px var(--gold)}
 .bottom-hud{display:flex;align-items:end;justify-content:space-between;gap:10px}.hint{font:10px 'DM Mono',monospace;color:#ffffff88;letter-spacing:.08em;text-shadow:0 1px 5px #000}.hint b{color:#fff}.sound-btn{pointer-events:auto;border:1px solid #ffffff35;background:#090b1688;color:#fff;border-radius:50%;width:38px;height:38px;font-size:16px;cursor:pointer}

